const s = "a";
const t = "b";
const n = 1;
export const c = s.localeCompare(t); // expect: nondeterminism
export const hours = new Date(0).getHours(); // expect: nondeterminism
export const text = n.toLocaleString(); // expect: nondeterminism
export const now = Date.now(); // expect: nondeterminism
export const empty = new Date(); // expect: nondeterminism
export const parts = new Date(2026, 0, 1).toISOString(); // expect: nondeterminism
export const set = new Date(0).setHours(1); // expect: nondeterminism
export const str = String(new Date(0)); // expect: nondeterminism
export const el = new Date(0)["getHours"](); // expect: nondeterminism
const d = new Date(0); // expect: nondeterminism
export const iso = d.toISOString();
export const call = Date(0); // expect: nondeterminism
export const refl = Reflect.construct(Date, []); // expect: nondeterminism
export const r1 = Math.random(); // expect: nondeterminism
export const r2 = Math["random"](); // expect: nondeterminism
const { random } = Math; // expect: nondeterminism
export const r3 = random();
export const sin = Math.sin(1); // expect: nondeterminism
export const lit = new Date("2026-09-26T19:40").toISOString(); // expect: nondeterminism
